    contributions = []
    for i in range(len(values)):
        x = values[i]
        p_x = 2 * x + 1 * (x ** 2) + 0 * (x ** 3)
        if i == 0:
            g_term = 0
        else:
            prev_sum = sum(values[:i])
            g_term = 1 * x * prev_sum
        total_contrib = p_x + g_term
